    private static String invalidBody() {
        return """
                {
                  "firstName": "",
                  "lastName": "Kowalski",
                  "email": "not-an-email",
                  "phone": "+48 600 100 200",
                  "nip": "123"
                }
                """;
    }

    private static CustomerResponse response() {
        return new CustomerResponse(1L, "Jan", "Kowalski", EMAIL, "+48 600 100 200", "1234567890");
    }
