  it('shows the ProblemDetail detail when the backend reports a conflict', async () => {
    fillValidCustomer();
    await submit();

    http.expectOne({ method: 'POST', url: '/api/customers' }).flush(
      {
        title: 'Conflict',
        status: 409,
